def parse_roman(s):
    if not isinstance(s, str) or not s:
        return None

    vals = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]

    n = 0
    i = 0
    length = len(s)
    for val, sym in vals:
        while s[i:i+len(sym)] == sym:
            n += val
            i += len(sym)

    if i != length:
        return None

    if n < 1 or n > 3999:
        return None

    def to_roman(num):
        result = []
        for val, sym in vals:
            while num >= val:
                result.append(sym)
                num -= val
        return ''.join(result)

    if to_roman(n) != s:
        return None

    return n

